			for _, p := range []*any{&a, &b} {
				for {
					switch (*p).(type) {
					case *string, *int64, *float64, *bool, *int, *[]string, *[]any, *map[string]any, *any:
						r := reflect.ValueOf(*p)
						_, again := (*p).(*any)
						if *p = nil; !r.IsZero() {
							*p = r.Elem().Interface()
						}
						if again && *p != nil {
							continue
						}
					case map[string]any, []any, []string:
						if reflect.ValueOf(*p).IsZero() {
							*p = nil
						}
					}
					break
				}
			}
